async function clearLegacy(){try{if('serviceWorker'in navigator){const regs=await navigator.serviceWorker.getRegistrations();await Promise.all(regs.map(r=>r.unregister()))}if('caches'in window){const keys=await caches.keys();await Promise.all(keys.map(k=>caches.delete(k)))}}catch{}}
function current(){const now=vNow();return{now,phase:getTimePhase(now),sleep:isSleepTime(state.routine,now,state.debug?.forceSleep),meal:getMealStatus(state,now),growth:getGrowthStage(state,now)}}
function updateArt(entity,pose,stage='baby'){const key=`${pose}:${stage}`;if(artState.get(entity)===key)return;const target=$('[data-cat-art]',entity);if(!target)return;target.innerHTML=renderCatPose(pose,stage);entity.dataset.pose=pose;artState.set(entity,key)}
