function whisper(msg,duration=3200){clearTimeout(whisperTimer);e.whisperText.textContent=msg;e.whisper.hidden=false;whisperTimer=setTimeout(()=>e.whisper.hidden=true,duration)}
function toast(msg,duration=2300){clearTimeout(toastTimer);e.toast.textContent=msg;e.toast.hidden=false;toastTimer=setTimeout(()=>e.toast.hidden=true,duration)}
function dismissHint(){e.firstRoomHint.classList.add('dismissed')}
function open(sheet){close();openSheet=sheet;e.backdrop.hidden=false;sheet.hidden=false;requestAnimationFrame(()=>$('[data-close]',sheet)?.focus({preventScroll:true}))}
