function setCat(pose,location=activeLocation,msg=null,duration=3200){activePose=pose;activeLocation=location;const g=getGrowthStage(state,vNow());e.mainCat.style.setProperty('--growth-scale',g.scale);setEntity(e.mainCat,pose,location,g.id);e.livingRoom.dataset.action=pose;if(msg)whisper(msg,duration)}
function natural(s=current()){if(s.sleep)return{pose:'sleep',location:'bed'};if(s.meal.overdue||state.fullness<38)return{pose:'look',location:'bowl'};if(state.energy<36)return{pose:'lie',location:'bed'};if(s.phase==='morning')return{pose:'look',location:'window'};return{pose:'sit',location:'center'}}
function render({preserve=false}={}){if(!state.onboarded)return;state=applyElapsedTime(state,vNow());save();const s=current();e.app.dataset.phase=s.phase;e.livingRoom.dataset.roomPhase=s.phase;e.petNameTitle.textContent=state.petName;e.dayLabel.textContent=`一緒に ${getDaysTogether(state,s.now)}日目`;e.debugTime.textContent=new Date(s.now).toLocaleString('ja-JP',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});e.debugState.textContent=saveHealthy?'保存 正常':'保存不可';e.settingsBreakfast.value=state.routine.breakfast;e.settingsDinner.value=state.routine.dinner;e.settingsWake.value=state.routine.wake;e.settingsBedtime.value=state.routine.bedtime;if(!busy&&!preserve){const h=natural(s);setCat(h.pose,h.location)}else{const g=getGrowthStage(state,s.now);e.mainCat.style.setProperty('--growth-scale',g.scale);updateArt(e.mainCat,activePose,g.id)}}
function showHome(){e.onboarding.classList.add('hidden');e.home.classList.remove('hidden');e.app.dataset.scene='home';render();scheduleIdle()}
function showOnboarding(){e.home.classList.add('hidden');e.onboarding.classList.remove('hidden');e.app.dataset.scene='onboarding';setEntity(e.previewCat,'peek','carrier','baby')}
function haptic(pattern=12){try{navigator.vibrate?.(pattern)}catch{}}
function zone(entity,event){const r=entity.getBoundingClientRect(),x=clamp((event.clientX-r.left)/r.width,0,1),y=clamp((event.clientY-r.top)/r.height,0,1);if(x>.73&&y>.35)return'tail';if(y<.42)return'head';if(x<.48)return'back';return'flank'}
function petMessage(z,pace,preview=false){const n=preview?'この子':state.petName;if(pace==='fast')return`${n}は耳を一度だけ動かし、指の速さを確かめるように顔を上げました。`;if(z==='head')return`${n}は目を細め、額を指先へ少し近づけました。`;if(z==='back')return`${n}は背中をゆるめ、ゆっくりした手の動きへ身体を預けました。`;if(z==='flank')return`${n}は呼吸を落ち着け、その場から離れずに手を見ています。`;return`${n}はしっぽを引き寄せ、触れられた場所を確認するように振り返りました。`}
async function petReact(entity,z,pace,preview=false){entity.classList.add('touched');setTimeout(()=>entity.classList.remove('touched'),720);if(preview){if(previewCompleted)return;previewCompleted=true;e.firstPrompt.classList.add('done');setEntity(e.previewCat,pace==='fast'?'attentive':'rub','center','baby');haptic(12);await wait(620);e.namePanel.hidden=false;setTimeout(()=>e.petNameInput.focus({preventScroll:true}),330);return}if(busy)return;dismissHint();const welcome=pace!=='fast'&&z!=='tail';state=recordPetting(state,z,pace,vNow());save();setCat(welcome?'rub':'attentive',activeLocation,petMessage(z,pace),3000);haptic(welcome?12:[8,22,8]);await wait(800);if(!busy)render();scheduleIdle()}
function bindPet(entity,{preview=false}={}){let p=null;entity.addEventListener('pointerdown',ev=>{if(!preview&&busy)return;entity.setPointerCapture?.(ev.pointerId);p={id:ev.pointerId,lx:ev.clientX,ly:ev.clientY,start:performance.now(),distance:0}});entity.addEventListener('pointermove',ev=>{if(!p||p.id!==ev.pointerId)return;p.distance+=Math.hypot(ev.clientX-p.lx,ev.clientY-p.ly);p.lx=ev.clientX;p.ly=ev.clientY});const end=ev=>{if(!p||p.id!==ev.pointerId)return;const pace=p.distance/Math.max(1,performance.now()-p.start)>1.05?'fast':'slow',z=zone(entity,ev);p=null;petReact(entity,z,pace,preview)};entity.addEventListener('pointerup',end);entity.addEventListener('pointercancel',()=>p=null);entity.addEventListener('keydown',ev=>{if(!['Enter',' '].includes(ev.key))return;ev.preventDefault();petReact(entity,'head','slow',preview)})}
async function feed(food){if(busy)return;close();stopToy(false);busy=true;dismissHint();e.bowlHotspot.dataset.food=food;e.bowlHotspot.classList.remove('draining');const tooFull=state.fullness>90&&food!=='treat';setCat('attentive',activeLocation,`${state.petName}が食器へ入った音に気づきました。`,2200);await wait(620);setCat('walk','bowl');await wait(1050);setCat('sniff','bowl',`${state.petName}はすぐに食べず、何度か香りを確かめています。`,2500);await wait(850);if(tooFull){setCat('look','bowl',`${state.petName}は今は空腹ではないようで、食器から少し距離を取りました。`,3100);await wait(1150);setCat('walk','center');await wait(950);busy=false;render();scheduleIdle();return}e.bowlHotspot.classList.add('draining');setCat('eat','bowl',`${state.petName}は自分のペースで食べ始めました。`,3000);await wait(food==='treat'?1600:2700);state=feedPet(state,food,vNow());save();setCat('satisfied','bowl',food==='treat'?`${state.petName}は食べ終え、もう一度だけ食器を見ました。`:`${state.petName}は口元を舐めてから、ゆっくり顔を上げました。`,3000);haptic([10,24,10]);await wait(900);e.bowlHotspot.dataset.food='empty';e.bowlHotspot.classList.remove('draining');if(current().sleep){setCat('walk','bed');await wait(1000);setCat('sleep','bed')}else{setCat('walk','center');await wait(950);setCat('sit','center')}busy=false;toast('食事の記録を残しました');render({preserve:current().sleep});scheduleIdle()}
async function windowVisit(){if(busy)return;busy=true;dismissHint();stopToy(false);setCat('attentive',activeLocation,`${state.petName}は窓の外の小さな音へ耳を向けました。`,2400);await wait(650);setCat('walk','window');await wait(1050);setCat('look','window',`${state.petName}は外を横切った影を、目だけで静かに追っています。`,3400);await wait(2600);state=addMemory(state,'窓辺で見つけたもの',`${state.petName}は外を動く影へ耳を向け、しばらく窓辺から離れなかった。`,vNow(),'window');save();setCat('walk','center');await wait(950);setCat('sit','center');busy=false;render({preserve:true});scheduleIdle()}
