function startToy(){if(busy)return;dismissHint();close();if(toySession){stopToy(true);return}busy=true;toySession={distance:0,completed:false};e.toy.hidden=false;e.toy.classList.remove('hidden');e.toy.style.setProperty('--toy-x','0px');e.toy.style.setProperty('--toy-y','0px');setCat('attentive','center',`${state.petName}は羽の先から目を離しません。ゆっくり動かしてみてください。`,3300)}
