async function completeToy(){if(!toySession||toySession.completed)return;toySession.completed=true;setCat('pounce','toy',`${state.petName}は姿勢を低くし、最後に前足で羽を押さえました。`,3200);haptic([10,20,10]);await wait(1450);state=recordPlay(state,vNow());save();stopToy(false);busy=false;setCat('sit','center');toast('遊んだ時間を記録しました');scheduleIdle()}
function bindToy(){let p=null;e.toy.addEventListener('pointerdown',ev=>{if(!toySession)return;e.toy.setPointerCapture?.(ev.pointerId);p={id:ev.pointerId,lx:ev.clientX,ly:ev.clientY}});e.toy.addEventListener('pointermove',ev=>{if(!toySession||!p||p.id!==ev.pointerId)return;const r=e.livingRoom.getBoundingClientRect(),x=clamp(ev.clientX-r.left-r.width/2,-r.width*.36,r.width*.36),y=clamp(ev.clientY-r.top-r.height*.52,-r.height*.25,r.height*.28);e.toy.style.setProperty('--toy-x',`${x}px`);e.toy.style.setProperty('--toy-y',`${y}px`);toySession.distance+=Math.hypot(ev.clientX-p.lx,ev.clientY-p.ly);p.lx=ev.clientX;p.ly=ev.clientY;if(toySession.distance>220)completeToy()});e.toy.addEventListener('pointerup',ev=>{if(!p||p.id!==ev.pointerId)return;p=null;if(toySession?.distance>105)completeToy()});e.toy.addEventListener('pointercancel',()=>p=null);e.toy.addEventListener('keydown',ev=>{if(!toySession||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter',' '].includes(ev.key))return;ev.preventDefault();toySession.distance+=70;if(toySession.distance>180)completeToy()})}
function scheduleIdle(){clearTimeout(idleTimer);if(!state.onboarded||busy||document.hidden)return;idleTimer=setTimeout(runIdle,7600+Math.random()*7200)}
async function runIdle(){if(busy||document.hidden)return scheduleIdle();const s=current();if(s.sleep){setCat('sleep','bed');return scheduleIdle()}busy=true;const actions=[['groom','center',`${state.petName}は前足を舐め、顔のまわりをゆっくり整えています。`,1900],['stretch','center',`${state.petName}は前足を伸ばし、背中を大きく伸ばしました。`,1600],['look','window',`${state.petName}はカーテンの小さな揺れへ耳を向けています。`,2300],['lie','bed',`${state.petName}は寝床へ身体を預け、しばらく目を細めています。`,2100]],a=actions[Math.floor(Math.random()*actions.length)];if(a[1]!==activeLocation){setCat('walk',a[1]);await wait(920)}setCat(a[0],a[1],a[2],a[3]+900);await wait(a[3]);if(a[1]!=='center'){setCat('walk','center');await wait(900)}setCat('sit','center');busy=false;scheduleIdle()}
